package com.fincore.fincore.auth;
import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.fincore.fincore.exception.ConflictException; import com.fincore.fincore.security.*; import com.fincore.fincore.user.*;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final AuthenticationManager auth; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,AuthenticationManager a,JwtService j){users=u;encoder=e;auth=a;jwt=j;} @Transactional public AuthResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase();if(users.existsByEmailIgnoreCase(email))throw new ConflictException("Email is already registered");User u=users.save(new User(r.firstName().trim(),r.lastName().trim(),email,encoder.encode(r.password()),Role.USER));var p=AuthenticatedUser.from(u);return new AuthResponse(jwt.generate(p),"Bearer",UserResponse.from(u));} public AuthResponse login(LoginRequest r){var a=auth.authenticate(new UsernamePasswordAuthenticationToken(r.email().trim().toLowerCase(),r.password()));var p=(AuthenticatedUser)a.getPrincipal();User u=users.findById(p.id()).orElseThrow();return new AuthResponse(jwt.generate(p),"Bearer",UserResponse.from(u));} }
